const j = $input.first().json;
const slug = String(j.slug || 'unknown');
const index = Number(j.index || 1);
const source_sftp_path = String(j.source_sftp_path || '');
const stamp = `${slug}-${index}-${Date.now()}`;
return [{
  json: {
    slug,
    index,
    source_sftp_path,
    source_local: `/tmp/syndicator-source-${stamp}.mp4`,
    frame_local: `/tmp/syndicator-frame-${stamp}.jpg`,
  },
}];

function cropBox(width, height, targetRatio, focus) {
  const fx = focus?.x ?? 0.5;
  const fy = focus?.y ?? 0.5;
  const srcRatio = width / height;
  let cropW;
  let cropH;
  if (srcRatio > targetRatio) {
    cropH = height;
    cropW = Math.round(height * targetRatio);
  } else {
    cropW = width;
    cropH = Math.round(width / targetRatio);
  }
  let left = Math.round(fx * width - cropW / 2);
  let top = Math.round(fy * height - cropH / 2);
  left = Math.min(Math.max(left, 0), width - cropW);
  top = Math.min(Math.max(top, 0), height - cropH);
  return { left, top, width: cropW, height: cropH };
}

function even(n) {
  return n % 2 === 0 ? n : n - 1;
}

function fitWithoutUpscale(cropW, cropH, maxW, maxH) {
  if (cropW <= maxW && cropH <= maxH) return { width: cropW, height: cropH };
  const scale = Math.min(maxW / cropW, maxH / cropH);
  return { width: even(Math.floor(cropW * scale)), height: even(Math.floor(cropH * scale)) };
}

function parseFocus(raw) {
  try {
    let t = raw?.content ?? raw?.text ?? raw?.[0]?.content?.[0]?.text ?? raw?.output?.[0]?.content?.[0]?.text ?? raw;
    if (typeof t !== 'string') t = JSON.stringify(t);
    const m = t.match(/\{[\s\S]*\}/);
    if (!m) return { x: 0.5, y: 0.5 };
    const j = JSON.parse(m[0]);
    return { x: Number(j.x) || 0.5, y: Number(j.y) || 0.5 };
  } catch (e) {
    return { x: 0.5, y: 0.5 };
  }
}

function pickMeta(meta) {
  const format = meta?.format || meta || {};
  let duration = Number(format.duration ?? meta?.duration ?? 0);
  const streams = meta?.streams || format.streams || [];
  const v = streams.find((s) => (s.codec_type || s.codecType) === 'video') || streams[0] || meta;
  const width = Number(v?.width ?? meta?.width ?? 0);
  const height = Number(v?.height ?? meta?.height ?? 0);
  if (!duration && meta?.duration) duration = Number(meta.duration);
  return { width, height, duration };
}

const trigger = $('Adapt Reel Trigger').first().json;
const slug = String(trigger.slug || '');
const index = Number(trigger.index || 1);
const sourcePath = String($('Resolve Paths').first().json.source_local || '');
const meta = pickMeta($('Analyze Source').first().json);
const focus = parseFocus($('Crop Focus').first().json);

const specs = [
  { name: 'facebook', aspect: '4:5', width: 1080, height: 1350, max_seconds: 240, pad_mode: 'crop' },
  { name: 'instagram', aspect: '4:5', width: 1080, height: 1350, max_seconds: 90, pad_mode: 'crop' },
  { name: 'x', aspect: '4:5', width: 1080, height: 1350, max_seconds: 140, pad_mode: 'crop' },
];

function reelGroupDir(spec, duration) {
  const aspect = (spec.aspect || 'orig').replace(':', 'x');
  const trimmed = spec.max_seconds != null && duration > spec.max_seconds;
  return trimmed ? `${aspect}-${spec.max_seconds}s` : aspect;
}

function reelSignature(spec, duration) {
  const trimmed = spec.max_seconds != null && duration > spec.max_seconds;
  const effectiveCap = trimmed ? spec.max_seconds : null;
  return [spec.aspect, spec.width, spec.height, spec.pad_mode, effectiveCap].join('|');
}

const groups = [];
const bySig = {};
const usedDirs = new Set();
for (const spec of specs) {
  const sig = reelSignature(spec, meta.duration);
  if (bySig[sig]) {
    bySig[sig].platforms.push(spec.name);
    continue;
  }
  let specDir = reelGroupDir(spec, meta.duration);
  if (usedDirs.has(specDir)) {
    const base = specDir;
    let i = 2;
    while (usedDirs.has(specDir)) {
      specDir = `${base}-${i}`;
      i += 1;
    }
  }
  usedDirs.add(specDir);
  const trimmed = spec.max_seconds != null && meta.duration > spec.max_seconds;
  const box = cropBox(meta.width, meta.height, spec.width / spec.height, focus);
  const out = fitWithoutUpscale(box.width, box.height, spec.width, spec.height);
  const group = {
    channel: spec.name,
    spec_dir: specDir,
    platforms: [spec.name],
    max_seconds: trimmed ? spec.max_seconds : null,
    crop: box,
    out,
    source_local: sourcePath,
    reel_local: `/tmp/syndicator-reel-${slug}-${index}-${specDir}.mp4`,
    cover_local: `/tmp/syndicator-cover-${slug}-${index}-${specDir}.jpg`,
    reel_sftp: `/syndicator/${slug}/reels/${specDir}/${index}.mp4`,
    cover_sftp: `/syndicator/${slug}/covers/${specDir}/${index}.jpg`,
  };
  bySig[sig] = group;
  groups.push(group);
}

return groups.map((g) => {
  const vf = `crop=${g.crop.width}:${g.crop.height}:${g.crop.left}:${g.crop.top},scale=${g.out.width}:${g.out.height}`;
  const trim = g.max_seconds != null ? ` -t ${g.max_seconds}` : '';
  const customArgs = `-y -i ${g.source_local} -vf "${vf}"${trim} -c:v libx264 -pix_fmt yuv420p -c:a aac -movflags +faststart ${g.reel_local}`;
  return { json: { ...g, customArgs, slug, index } };
});

const g = $('Plan Reel Groups').item.json;
return {
  json: {
    platforms: g.platforms,
    reel_sftp: g.reel_sftp,
    cover_sftp: g.cover_sftp,
    reel_local: g.reel_local,
    cover_local: g.cover_local,
  },
  binary: $input.item.binary,
};

const items = $input.all().map((i) => i.json);
const files = { reels: {}, covers: {} };
for (const g of items) {
  for (const p of g.platforms || []) {
    files.reels[p] = g.reel_sftp;
    files.covers[p] = g.cover_sftp;
  }
}
const trigger = $('Adapt Reel Trigger').first().json;
return [{
  json: {
    slug: trigger.slug,
    index: trigger.index,
    source_sftp_path: trigger.source_sftp_path,
    files,
  },
}];
